import React, { useState } from "react";
import { motion } from "framer-motion";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from "recharts";

export default function App() {

  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");

  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState("");

  const handleRun = async () => {
    setLoading(true);
    setData(null);

    setStep("🔍 Fetching research...");
    setTimeout(() => setStep("📊 Ranking publications..."), 800);
    setTimeout(() => setStep("🤖 Generating AI summary..."), 1200);

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ disease, intent, location })
      });

      const result = await res.json();
      setData(result);

    } catch (err) {
      console.error(err);
      alert("❌ Backend not connected");
    }

    setLoading(false);
    setStep("");
  };

  // ✅ FIXED chartData
  const chartData = data
    ? [
        {
          name: "Results",
          Papers: data.publications?.length || 0,
          Trials: data.clinical_trials?.length || 0
        }
      ]
    : [];

  return (
    <motion.div style={container} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>

      {/* LEFT */}
      <div style={leftPanel}>
        <h2>Curalink X</h2>

        <input
          placeholder="Filter by disease"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
          style={input}
        />

        <h3>Stats</h3>
        <p>📄 Papers: {data?.publications?.length || 0}</p>
        <p>🧪 Trials: {data?.clinical_trials?.length || 0}</p>
      </div>

      {/* CENTER */}
      <div style={centerPanel}>
        <h1>🧠 AI Medical Research Copilot</h1>

        <textarea
          placeholder="Ask your medical research question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
          style={textarea}
        />

        <motion.button onClick={handleRun} style={button}>
          {loading ? "Running..." : "Send message"}
        </motion.button>

        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          style={input}
        />

        {loading && <p>⏳ {step}</p>}
      </div>

      {/* RIGHT */}
      <div style={rightPanel}>

        {/* ✅ SAFE CHART FIX */}
        {data && chartData.length > 0 && (
          <motion.div style={card}>
            <h3>📊 Research Analytics</h3>

            <div style={{ width: "100%", height: 220 }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData}>
                  <XAxis dataKey="name" stroke="#ccc" />
                  <YAxis stroke="#ccc" />
                  <Tooltip />
                  <Bar dataKey="Papers" fill="#3b82f6" />
                  <Bar dataKey="Trials" fill="#8b5cf6" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </motion.div>
        )}

        {/* SUMMARY */}
        <motion.div style={card}>
          <h3>Dynamic Insights</h3>
          {!data && <p>No data yet</p>}
          {data && <p>{data.summary}</p>}
        </motion.div>

        {/* PAPERS */}
        <motion.div style={card}>
          <h3>Research Papers</h3>

          {!data && !loading && <p>No publications yet</p>}

          {data?.publications?.map((p, i) => (
            <div key={i} style={item}>
              <strong>{p.title}</strong>
              <p style={meta}>{p.source} • {p.year}</p>
              <a href={p.link} target="_blank" rel="noreferrer" style={link}>
                View Source
              </a>
            </div>
          ))}
        </motion.div>

        {/* TRIALS */}
        <motion.div style={card}>
          <h3>Clinical Trials</h3>

          {!data && !loading && <p>No trials yet</p>}

          {data?.clinical_trials?.map((t, i) => (
            <div key={i} style={item}>
              <strong>{t.title}</strong>
              <p style={meta}>Status: {t.status}</p>
            </div>
          ))}
        </motion.div>

      </div>
    </motion.div>
  );
}

/* STYLES SAME AS YOURS (no change needed) */

/* ================= STYLES ================= */

const container = {
  display: "flex",
  height: "100vh",
  background: "linear-gradient(135deg,#0f172a,#1e293b,#020617)",
  color: "white",
  fontFamily: "system-ui, sans-serif"
};

const leftPanel = {
  width: "260px",
  padding: "20px",
  backdropFilter: "blur(20px)",
  background: "rgba(255,255,255,0.05)",
  borderRight: "1px solid rgba(255,255,255,0.1)"
};

const centerPanel = {
  flex: 1,
  padding: "20px"
};

const rightPanel = {
  width: "400px",
  padding: "20px",
  backdropFilter: "blur(20px)",
  background: "rgba(255,255,255,0.05)",
  borderLeft: "1px solid rgba(255,255,255,0.1)",
  overflowY: "auto"
};

const input = {
  width: "100%",
  padding: "12px",
  marginTop: "10px",
  background: "rgba(255,255,255,0.05)",
  color: "white",
  border: "1px solid rgba(255,255,255,0.1)",
  borderRadius: "10px",
  outline: "none"
};

const textarea = {
  width: "100%",
  height: "120px",
  padding: "12px",
  marginTop: "10px",
  background: "rgba(255,255,255,0.05)",
  color: "white",
  border: "1px solid rgba(255,255,255,0.1)",
  borderRadius: "10px",
  outline: "none"
};

const button = {
  marginTop: "15px",
  padding: "14px",
  width: "100%",
  background: "linear-gradient(135deg,#3b82f6,#8b5cf6,#6366f1)",
  color: "white",
  border: "none",
  borderRadius: "12px",
  cursor: "pointer",
  fontWeight: "bold",
  fontSize: "15px"
};

const card = {
  background: "rgba(255,255,255,0.06)",
  padding: "15px",
  marginTop: "15px",
  borderRadius: "12px",
  border: "1px solid rgba(255,255,255,0.08)"
};

const item = {
  borderTop: "1px solid rgba(255,255,255,0.08)",
  marginTop: "10px",
  paddingTop: "10px"
};

const meta = {
  fontSize: "12px",
  opacity: 0.7
};

const link = {
  fontSize: "12px",
  color: "#60a5fa",
  textDecoration: "none"
};
